export interface Note { id: number; title: string; body: string }

export class NoteStore {
  private notes = new Map<number, Note>();
  private nextId = 1;

  add(title: string, body: string): Result<Note> {
    if (!title.trim()) return err('title required');
    const note = { id: this.nextId++, title, body };
    this.notes.set(note.id, note);
    return ok(note);
  }

  get(id: number): Result<Note> {
    const n = this.notes.get(id);
    return n ? ok(n) : err('not found');
  }

  list(): Note[] {
    return [...this.notes.values()];
  }
}
