import type { NoteStore } from './note-store.ts';
import { searchNotes } from './search.ts';
import { type Result, ok, err } from './result.ts';
import { parseJson } from './json-body.ts';

export interface ApiResponse { status: number; body: unknown }

const json = (status: number, body: unknown): ApiResponse => ({ status, body });
const fail = (status: number, error: string): ApiResponse => json(status, { error });
const notFound = (): ApiResponse => fail(404, 'not found');

function parseNoteInput(raw: string): Result<{ title: string; body: string }> {
  const parsed = parseJson(raw);
  if (!parsed.ok) return parsed;
  const p = parsed.value;
  if (typeof p !== 'object' || p === null || Array.isArray(p)) return err('object required');
  const { title, body = '' } = p as Record<string, unknown>;
  if (typeof title !== 'string' || typeof body !== 'string') return err('title and body must be strings');
  return ok({ title, body });
}

function createNote(store: NoteStore, raw: string): ApiResponse {
  const input = parseNoteInput(raw);
  if (!input.ok) return fail(400, input.error);
  const r = store.add(input.value.title, input.value.body);
  return r.ok ? json(201, r.value) : fail(400, r.error);
}

function getNote(store: NoteStore, idText: string): ApiResponse {
  if (!/^[1-9]\d*$/.test(idText)) return notFound();
  const r = store.get(Number(idText));
  return r.ok ? json(200, r.value) : notFound();
}

function search(store: NoteStore, params: URLSearchParams): ApiResponse {
  const r = searchNotes(store.list(), params.get('q') ?? '');
  return r.ok ? json(200, r.value) : fail(400, r.error);
}

function route(store: NoteStore, method: string, u: URL, body: string): ApiResponse {
  const path = u.pathname;
  if (method === 'POST') return path === '/notes' ? createNote(store, body) : notFound();
  if (method !== 'GET') return notFound();
  if (path === '/health') return json(200, { status: 'ok' });
  if (path === '/notes') return json(200, store.list());
  if (path === '/search') return search(store, u.searchParams);
  return path.startsWith('/notes/') ? getNote(store, path.slice(7)) : notFound();
}

export function handleRequest(store: NoteStore, method: string, url: string, body: string): ApiResponse {
  try {
    return route(store, method, new URL(url, 'http://localhost'), body);
  } catch {
    return fail(400, 'bad request');
  }
}
