{"command":"cat > tests/structure.test.ts <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';

const read = (p: string): string => readFileSync(new URL(`../${p}`, import.meta.url), 'utf8');
const importsOf = (file: string): string[] =>
  [...read(file).matchAll(/from\s+'([^']+)'/g)].map((m) => m[1] as string);
const srcFiles = readdirSync(new URL('../src/', import.meta.url)).filter((f) => f.endsWith('.ts'));
const edge = ['notes-api.ts', 'http-server.ts'];
const core = ['note-store.ts', 'search.ts', 'result.ts'];

test('AC-13 status codes only in edge modules; core modules import no edge modules', () => {
  for (const f of core) {
    assert.doesNotMatch(read(`src/${f}`), /\b(statusCode|[1-5]\d\d)\b.*status|status.*\b[45]\d\d\b/i);
    for (const imp of importsOf(`src/${f}`)) {
      assert.ok(!/notes-api|http-server|json-body|main/.test(imp), `${f} imports ${imp}`);
    }
  }
  for (const f of srcFiles.filter((x) => !edge.includes(x) && !core.includes(x))) {
    assert.doesNotMatch(read(`src/${f}`), /statusCode|writeHead/, `${f} uses status codes`);
  }
});

test('AC-15 no dependencies field; src imports only node: built-ins or local modules', () => {
  const pkg = JSON.parse(read('package.json')) as Record<string, unknown>;
  assert.equal('dependencies' in pkg, false);
  for (const f of srcFiles) {
    for (const imp of importsOf(`src/${f}`)) {
      assert.ok(imp.startsWith('node:') || imp.startsWith('./'), `${f} imports ${imp}`);
    }
  }
});

test('AC-18 package.json defines test, lint and typecheck scripts', () => {
  const scripts = (JSON.parse(read('package.json')) as { scripts: Record<string, string> }).scripts;
  assert.match(scripts['test'] ?? '', /node --test/);
  assert.match(scripts['lint'] ?? '', /eslint/);
  assert.match(scripts['typecheck'] ?? '', /tsc --noEmit/);
});

