import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import type { AddressInfo } from 'node:net';
import { NoteStore } from '../src/note-store.ts';
import { createServer, resolvePort } from '../src/http-server.ts';
import type { ApiResponse } from '../src/notes-api.ts';

type Handler = (s: NoteStore, m: string, u: string, b: string) => ApiResponse;

async function start(store = new NoteStore(), handler?: Handler) {
  const lines: string[] = [];
  const server = createServer(store, { log: (l) => lines.push(l), handler });
  await new Promise<void>((r) => server.listen(0, r));
  const base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  return { server, base, lines, store };
}

test('AC-4 body over 1 MiB gets 413 and stores nothing', async () => {
  const { server, base, store } = await start();
  const big = JSON.stringify({ title: 't', body: 'x'.repeat(1024 * 1024 + 10) });
  const res = await fetch(`${base}/notes`, { method: 'POST', body: big });
  assert.equal(res.status, 413);
  assert.equal(typeof ((await res.json()) as { error: string }).error, 'string');
  assert.equal(store.list().length, 0);
  server.close();
});

test('AC-11 every response is application/json', async () => {
  const { server, base } = await start();
  for (const [m, p] of [['GET', '/health'], ['GET', '/nope'], ['POST', '/notes']]) {
    const res = await fetch(base + p, { method: m, body: m === 'POST' ? '{bad' : undefined });
    assert.match(res.headers.get('content-type') ?? '', /^application\/json/);
    await res.text();
  }
  server.close();
});

test('AC-12 unexpected handler failure returns 500 and server survives', async () => {
  const boom: Handler = (_s, _m, u) => {
    if (u === '/boom') throw new Error('secret');
    return { status: 200, body: { ok: 1 } };
  };
  const { server, base } = await start(new NoteStore(), boom);
  const res = await fetch(`${base}/boom`);
  assert.equal(res.status, 500);
  assert.deepEqual(await res.json(), { error: 'internal error' });
  assert.equal((await fetch(`${base}/ok`)).status, 200);
  server.close();
});

test('AC-19 one log line per request in expected format', async () => {
  const { server, base, lines } = await start();
  await (await fetch(`${base}/notes`, { method: 'POST', body: '{"title":"a"}' })).text();
  assert.equal(lines.length, 1);
  assert.match(lines[0], /^POST \/notes 201 \d+ms$/);
  server.close();
});

test('AC-20 logs never contain bodies or query strings', async () => {
  const { server, base, lines } = await start();
  const s = 'SENTINEL-9f3a';
  await (await fetch(`${base}/notes`, { method: 'POST', body: JSON.stringify({ title: s, body: s }) })).text();
  await (await fetch(`${base}/search?q=${s}`)).text();
  assert.equal(lines.length, 2);
  assert.ok(lines.every((l) => !l.includes(s) && !l.includes('?')));
  server.close();
});

test('AC-24 resolvePort uses PORT or falls back to 8081', () => {
  assert.equal(resolvePort({ PORT: '9123' }), 9123);
  assert.equal(resolvePort({}), 8081);
});

test('AC-24 AC-23 main listens on PORT and exits 0 on SIGTERM', async () => {
  const port = 20000 + Math.floor(Math.random() * 20000);
  const p = spawn('node', ['src/main.ts'], { env: { ...process.env, PORT: String(port) } });
  const exited = new Promise<number | null>((r) => p.on('close', r));
  let res: Response | undefined;
  for (let i = 0; i < 50 && !res; i++) {
    res = await fetch(`http://127.0.0.1:${port}/health`).catch(() => undefined);
    if (!res) await new Promise((r) => setTimeout(r, 100));
  }
  assert.equal(res?.status, 200);
  const t = Date.now();
  p.kill('SIGTERM');
  assert.equal(await exited, 0);
  assert.ok(Date.now() - t < 10000);
});

