import { NoteStore } from './note-store.ts';
import { handleRequest, type ApiResponse } from './notes-api.ts';

export const MAX_BODY_BYTES = 1024 * 1024;
const DEFAULT_PORT = 8081;

type Handler = (store: NoteStore, method: string, url: string, body: string) => ApiResponse;

export interface ServerOptions {
  log?: (line: string) => void;
  handler?: Handler;
}

export function resolvePort(env: Record<string, string | undefined>): number {
  const n = Number(env.PORT);
  return env.PORT && Number.isInteger(n) && n >= 0 && n < 65536 ? n : DEFAULT_PORT;
}

function send(res: http.ServerResponse, r: ApiResponse): void {
  const payload = JSON.stringify(r.body);
  res.writeHead(r.status, {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

/** Resolves with the body text, or null when it exceeds the limit. */
function readBody(req: http.IncomingMessage): Promise<string | null> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooBig = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY_BYTES) tooBig = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve(tooBig ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', () => resolve(null));
  });
}

async function respond(store: NoteStore, handler: Handler, req: http.IncomingMessage): Promise<ApiResponse> {
  try {
    const body = await readBody(req);
    if (body === null) return { status: 413, body: { error: 'payload too large' } };
    return handler(store, req.method ?? 'GET', req.url ?? '/', body);
  } catch {
    return { status: 500, body: { error: 'internal error' } };
  }
}

function pathOf(url: string | undefined): string {
  try {
    return new URL(url ?? '/', 'http://localhost').pathname;
  } catch {
    return '/';
  }
}

export function createServer(store: NoteStore, options: ServerOptions = {}): http.Server {
  const log = options.log ?? ((l: string) => console.log(l));
  const handler = options.handler ?? handleRequest;
  return http.createServer((req, res) => {
    const start = performance.now();
    void respond(store, handler, req).then((r) => {
      send(res, r);
      const ms = Math.round(performance.now() - start);
      log(`${req.method ?? 'GET'} ${pathOf(req.url)} ${r.status} ${ms}ms`);
    });
  });
}
